package com.college.notes.repository;
import com.college.notes.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.util.*;
public interface NoteRepository extends JpaRepository<Note,Long>{ List<Note> findByFacultyId(Long facultyId); @Query("select n from Note n where n.faculty.id=:facultyId and (:q='' or lower(n.title) like lower(concat('%',:q,'%')) or lower(coalesce(n.description,'')) like lower(concat('%',:q,'%'))) and (:subjectId is null or n.subject.id=:subjectId)") List<Note> searchForFaculty(@Param("facultyId") Long facultyId,@Param("q") String q,@Param("subjectId") Long subjectId); @Query("select n from Note n where (:q='' or lower(n.title) like lower(concat('%',:q,'%')) or lower(coalesce(n.description,'')) like lower(concat('%',:q,'%')) or lower(n.subject.name) like lower(concat('%',:q,'%'))) and (:subjectId is null or n.subject.id=:subjectId)") List<Note> search(@Param("q") String q,@Param("subjectId") Long subjectId); }
